WITH enriched AS (SELECT id, store_id, product_id, last_restock, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY quantity DESC) quantity_percent_rank, AVG(quantity) OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) quantity_avg_6, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_quantity FROM inventory WHERE quantity BETWEEN 96 AND 196) SELECT CASE WHEN quantity_percent_rank >= 0.78 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_percent_rank_tier, store_id, APPROX_PERCENTILE(last_known_quantity, ARRAY(0.25, 0.5, 0.75)) AS last_known_quantity_quartiles, COUNT(DISTINCT id) AS distinct_ids, AVG(last_known_quantity) AS avg_last_known_quantity, APPROX_PERCENTILE(quantity_avg_6, ARRAY(0.25, 0.5, 0.75)) AS quantity_avg_6_quartiles, COUNT(DISTINCT store_id) AS distinct_store_ids, DENSE_RANK() OVER (PARTITION BY CASE WHEN quantity_percent_rank >= 0.78 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(DISTINCT store_id) DESC) AS distinct_store_ids_dense_rank FROM enriched GROUP BY CASE WHEN quantity_percent_rank >= 0.78 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id
